corrected_code:
router.get('/api/chats/:chatId/messages', async (req, res) => {
  const chat = await Chat.findOne({ _id: req.params.chatId, participants: req.user._id }).populate('messages');
  if (!chat) return res.status(403).send('Not a participant');
  res.json(chat.messages);
});
